package com.luatweaker.api.pal;

public interface IPlatformNetwork {
    void sendPayloadPacket(String playerUuid, String channelName, String dataJson);
    void broadcastPayloadPacket(String channelName, String dataJson);
    void sendPayloadPacketToServer(String channelName, String dataJson);

    /**
     * Sends one RemoteFunction protocol packet to a specific player.
     *
     * @param playerUuid   target player
     * @param requestId    correlation id generated by the requesting side
     * @param phase        {@code RpcPhase.INVOKE} or {@code RpcPhase.RESULT}
     * @param functionName RemoteFunction channel name
     * @param dataJson     JSON argument array (invoke) or single-result array (result)
     * @param error        empty when successful; otherwise the failure message
     */
    default void sendRpcPacket(String playerUuid, String requestId, String phase,
                       String functionName, String dataJson, String error) {}

    /**
     * Sends one RemoteFunction protocol packet to the server.
     *
     * @see #sendRpcPacket(String, String, String, String, String, String)
     */
    default void sendRpcPacketToServer(String requestId, String phase,
                              String functionName, String dataJson, String error) {}
}
